package com.onebytelabs.zlplay.project;
import org.json.*;import java.util.*;import java.text.Normalizer;
/** Read-only desktop setlist: explicit source choices and order survive relocation. */
public final class SetlistSpec {
 public String title;public final List<Song> songs=new ArrayList<>();
 public static final class Song {public String id,name,folder,project,originalKey,tonalKey;}
 private static String key(String s){return Normalizer.normalize(s,Normalizer.Form.NFC).toLowerCase(Locale.ROOT);}
 private static String path(String s)throws ProjectSpec.Invalid {String text=s.replace('\\','/');if(text.contains("://")||text.startsWith("/")||text.matches("^[A-Za-z]:.*"))throw new ProjectSpec.Invalid();List<String> parts=new ArrayList<>();for(String p:text.split("/")){if(p.equals(".."))throw new ProjectSpec.Invalid();if(!p.isEmpty()&&!p.equals("."))parts.add(p);}if(parts.isEmpty())throw new ProjectSpec.Invalid();return String.join("/",parts);}
 private static String text(JSONObject row,String key,String fallback){return row.isNull(key)?fallback:row.optString(key,fallback);}
 private static String leaf(String s){s=s.replace('\\','/');return s.substring(s.lastIndexOf('/')+1);}
 private static String find(ProjectFolder files,String wanted,String scope)throws ProjectSpec.Invalid {String exact=null;for(String file:files.files.keySet())if(key(file).equals(key(wanted))){if(exact!=null)throw new ProjectSpec.Invalid();exact=file;}if(exact!=null)return exact;String found=null;for(String file:files.files.keySet())if(key(file).startsWith(key(scope+"/"))&&key(leaf(file)).equals(key(leaf(wanted)))){if(found!=null)return null;found=file;}return found;}
 public static SetlistSpec parse(String text,String manifest,ProjectFolder files)throws Exception{
  JSONObject root=new JSONObject(text);if(!root.optString("type").equals("zlplay-library")||root.optInt("version",-1)!=1)throw new ProjectSpec.Invalid();JSONArray rows=root.optJSONArray("songs");if(rows==null||rows.length()<1||rows.length()>256)throw new ProjectSpec.Invalid();SetlistSpec result=new SetlistSpec();result.title=leaf(manifest).replaceFirst("(?i)\\.(zlset|zlplaylibrary)$","");String parent=manifest.contains("/")?manifest.substring(0,manifest.lastIndexOf('/')+1):"";Map<String,Song> ids=new LinkedHashMap<>();
  for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);Song song=new Song();song.name=text(row,"name",text(row,"folder",""));song.id=text(row,"id",song.name);if(song.name.trim().isEmpty()||song.id.trim().isEmpty()||ids.containsKey(song.id))throw new ProjectSpec.Invalid();song.folder=parent+path(text(row,"folder",song.name));song.originalKey=text(row,"originalKey","");song.tonalKey=text(row,"tonalKey","");String source=text(row,"source","");if(source.isEmpty())source=text(row,"project","");if(source.isEmpty())source=text(row,"rpp","");if(!source.isEmpty()){source=source.replace('\\','/');if(source.matches("^[A-Za-z]:/.*")||source.startsWith("/"))source=leaf(source);String selected=song.folder+"/"+path(source);song.project=find(files,selected,song.folder);if(song.project!=null&&!song.project.toLowerCase(Locale.ROOT).matches(".*\\.(zlplay|rpp)$"))throw new ProjectSpec.Invalid();}else{for(String file:files.projects())if(key(file).startsWith(key(song.folder+"/"))){if(song.project!=null){song.project=null;break;}song.project=file;}}ids.put(song.id,song);}
  Set<String> included=new HashSet<>();JSONArray order=root.optJSONArray("order");if(order!=null){if(order.length()>256)throw new ProjectSpec.Invalid();for(int i=0;i<order.length();i++){String id=order.getString(i);Song song=ids.get(id);if(song==null)for(Song entry:ids.values())if(entry.name.equals(id)||entry.folder.equals(parent+id)){if(song!=null)throw new ProjectSpec.Invalid();song=entry;}if(song==null)throw new ProjectSpec.Invalid();result.songs.add(song);included.add(song.id);}}
  for(Song song:ids.values())if(!included.contains(song.id))result.songs.add(song);if(result.songs.size()>256)throw new ProjectSpec.Invalid();return result;
 }
 public int unavailableCount(){int count=0;for(Song song:songs)if(song.project==null)count++;return count;}
 public int nextAvailable(int after){for(int i=Math.max(0,after+1);i<songs.size();i++)if(songs.get(i).project!=null)return i;return -1;}
 public int availableFrom(int index){int start=Math.max(0,Math.min(index,songs.size()-1)),found=nextAvailable(start-1);return found>=0?found:nextAvailable(-1);}
 private static int note(String key){String s=key.trim().replace("♭","b").replace("♯","#").toUpperCase(Locale.ROOT);if(!s.matches("[A-G](?:#|B)?(?:M|MIN|MAJ)?"))return -1;int n;switch(s.charAt(0)){case 'C':n=0;break;case 'D':n=2;break;case 'E':n=4;break;case 'F':n=5;break;case 'G':n=7;break;case 'A':n=9;break;case 'B':n=11;break;default:return -1;}if(s.length()>1){if(s.charAt(1)=='#')n++;else if(s.charAt(1)=='B')n--;}return(n+12)%12;}
 public static boolean needsTranspose(Song song){int original=note(song.originalKey),target=note(song.tonalKey);return original>=0&&target>=0&&original!=target;}
}
